<script setup>
import { onBeforeUnmount, reactive, ref } from 'vue'
import { governanceRead, governanceWrite } from '../../governance/api.js'
import { canGovernance as can } from '../../governance/permissions.js'
import { createClientId } from '../../clientId.js'
import { activeRun, conflictMessage, label, time } from '../../governance/helpers.js'
const props=defineProps({devices:Array,modelValue:Array})
const emit=defineEmits(['update:modelValue'])
const inspected=ref(null),facts=ref([]),factPage=ref(1),factTotal=ref(0)
const items=ref([]),total=ref(0),page=ref(1),error=ref(''),loading=ref(false),saving=ref(false),dialog=ref(false),opened=ref(false),form=reactive({}),statistics=reactive({})
let token=0,timer=0,disposed=false
function stop(){clearTimeout(timer);timer=0}
async function load(){const generation=++token;loading.value=true;error.value='';stop();try{const value=await governanceRead('historical-projections','','',{limit:20,offset:(page.value-1)*20});if(generation!==token||disposed)return;items.value=value.items||[];total.value=value.total??items.value.length;for(const row of items.value.filter(row=>row.snapshotId)){const result=await governanceRead('historical-projections',row.id,'snapshot');if(generation!==token||disposed)return;statistics[row.id]={...(result.statistics||{}),limitations:result.limitations||[],missingSources:result.missingSources||[]}}if(opened.value&&items.value.some(activeRun))timer=setTimeout(load,2500)}catch(cause){if(generation===token)error.value=cause.message}finally{if(generation===token)loading.value=false}}
function create(){Object.assign(form,{deviceIds:[],range:null,historicalSources:['POSTGRESQL'],projectionLimit:null,idempotencyKey:createClientId()});dialog.value=true;error.value=''}
async function save(){if(saving.value)return;saving.value=true;try{if(!form.deviceIds.length||!form.range||!(form.range[1]>form.range[0])||!form.historicalSources.length)throw new Error('请选择明确设备、有效历史窗口与存储来源');await governanceWrite('historical-projections','','',{deviceIds:form.deviceIds,start:form.range[0],end:form.range[1],idempotencyKey:form.idempotencyKey,parameters:{historicalSources:form.historicalSources,timeBasis:'EVENT_AT',...(form.projectionLimit>0?{projectionLimit:form.projectionLimit}:{})}});dialog.value=false;page.value=1;await load()}catch(cause){error.value=conflictMessage(cause)}finally{saving.value=false}}
async function cancel(row){if(saving.value)return;saving.value=true;try{await governanceWrite('historical-projections',row.id,'stop',{expectedVersion:row.version,idempotencyKey:createClientId()});await load()}catch(cause){error.value=conflictMessage(cause)}finally{saving.value=false}}
async function inspect(row){inspected.value=row;factPage.value=1;await loadFacts()}
async function loadFacts(){if(!inspected.value)return;loading.value=true;try{const value=await governanceRead('historical-projections',inspected.value.id,'observations',{limit:20,offset:(factPage.value-1)*20});facts.value=(value.items||[]).map(row=>({...row.body,id:row.id}));factTotal.value=value.total??facts.value.length}catch(cause){error.value=cause.message}finally{loading.value=false}}
function toggle(row,checked){const ids=props.modelValue||[];emit('update:modelValue',checked?[...new Set([...ids,row.id])]:ids.filter(id=>id!==row.id))}
onBeforeUnmount(()=>{disposed=true;token++;stop()})
</script>
<template><details @toggle="opened=$event.target.open;opened?load():stop()"><summary>高级：受控历史归一化投影</summary><div class="gov-stack"><p class="gov-meta">只按本次明确设备、窗口和来源创建持久任务。历史输入保留缺口与部分覆盖；普通分析只引用人工选中的固定投影，生产告警状态不变。</p><div class="gov-actions"><ui-button v-if="can('POST /api/v1/alarm-governance/historical-projections')" size="small" @click="create">创建有界历史投影</ui-button><ui-button size="small" :loading="loading" @click="load">刷新历史任务</ui-button></div><ui-alert v-if="error&&!dialog" :title="error" type="error" :closable="false"/><article v-for="row in items" :key="row.id" class="gov-card"><div class="gov-toolbar"><strong>{{label(row.status)}} · {{time(row.start)}} ～ {{time(row.end)}}</strong><ui-checkbox v-if="row.snapshotId&&['PARTIAL','SUCCEEDED'].includes(row.status)" :model-value="(modelValue||[]).includes(row.id)" @update:model-value="value=>toggle(row,value)">本次分析引用此固定投影</ui-checkbox></div><p class="gov-meta">{{row.deviceIds?.map(id=>devices.find(device=>device.id===id)?.name||id).join('、')}} · 阶段 {{row.stage}} · 实际处理 {{row.processed||0}} 条 · {{row.error}}</p><p v-if="statistics[row.id]" class="gov-meta">已扫描 {{statistics[row.id].messageScanned??'未知'}} 条 · 归一化事实 {{statistics[row.id].normalizedFacts??'未知'}} 条 · 完成批次 {{statistics[row.id].completedBatches??'未知'}} · 未包含 {{statistics[row.id].omittedMessages??'未知'}} 条</p><p v-for="source in statistics[row.id]?.sourceProgress||[]" :key="source.source" class="gov-meta">{{source.source}} · {{source.status}} · 已扫描 {{source.messageScanned}} 条 / 未包含 {{source.omittedMessages}} 条 · 读取 {{time(source.readAt)}} · {{source.exhausted?'本次查询已读到末尾，完整历史仍未证明':'仍有来源边界或缺口'}}</p><p v-for="reason in statistics[row.id]?.limitations||[]" :key="reason" class="gov-meta">{{label(reason)}}</p><ui-button v-if="row.snapshotId" text size="small" @click="inspect(row)">查看固定归一化事实</ui-button><ui-button v-if="activeRun(row)&&can('POST /api/v1/alarm-governance/historical-projections/:id/stop')" text size="small" :loading="saving" @click="cancel(row)">停止历史投影</ui-button></article><ui-empty v-if="!items.length&&!loading" description="尚无当前授权的历史投影。"/><ui-pagination :current-page="page" :page-size="20" :total="total" @current-change="value=>{page=value;load()}"/></div></details><ui-dialog v-model="dialog" title="创建受控历史归一化任务" width="min(760px,94vw)"><div class="gov-dialog-body"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><ui-form label-position="top" :disabled="saving"><ui-form-item label="明确投影设备" required><ui-select v-model="form.deviceIds" multiple filterable><ui-option v-for="row in devices" :key="row.id" :value="row.id" :label="row.name||row.id"/></ui-select></ui-form-item><ui-form-item label="有界历史投影窗口" required><ui-date-range v-model="form.range"/></ui-form-item><ui-form-item label="实际历史存储来源" required><ui-select v-model="form.historicalSources" multiple><ui-option value="POSTGRESQL" label="PostgreSQL成功解析输入"/><ui-option value="CLICKHOUSE" label="ClickHouse历史成功解析输入"/></ui-select></ui-form-item><ui-form-item label="本次归一化上限（选填）"><ui-input-number v-model="form.projectionLimit" :min="1" :precision="0"/></ui-form-item><p class="gov-meta">选择任务不表示历史完整。普通分析设备必须包含投影全部设备，分析窗口必须落在投影窗口内，系统会核对边界。</p></ui-form></div><template #footer><ui-button :disabled="saving" @click="dialog=false">取消</ui-button><ui-button type="primary" :loading="saving" @click="save">创建持久投影任务</ui-button></template></ui-dialog><ui-dialog :model-value="!!inspected" title="历史投影的固定逐次事实" width="min(760px,94vw)" @update:model-value="value=>{if(!value)inspected=null}"><div class="gov-dialog-body"><p class="gov-meta">固定任务 {{inspected?.id}} · 历史接受状态未知，生产告警状态不变。</p><article v-for="row in facts" :key="row.id" class="gov-card"><strong>{{label(row.factKind)}} · {{row.alarmType}} · {{row.deviceId}}</strong><p class="gov-meta">{{time(row.eventAt)}} · {{row.signalKey}} · {{label(row.timeQuality)}} · {{row.historicalQuality}}</p><p class="gov-meta">源身份 {{row.sourceEventId}} / {{row.sourceFieldPath||row.eventIndex}}</p></article><ui-empty v-if="!facts.length&&!loading" description="该投影没有可归一化的报警逐次事实；成功属性报文不等于报警。"/><ui-pagination :current-page="factPage" :page-size="20" :total="factTotal" @current-change="value=>{factPage=value;loadFacts()}"/></div></ui-dialog></template>
